import React from 'react';
import { Container, Dot } from './LoadingDots.styles';
import { LoadingDotsTypes } from './LoadingDots.types';

function LoadingDotsComponent(
  { color = 'mono', size = 'large', dataTestId, ariaLabel, ...props }: LoadingDotsTypes,
  forwardedRef: React.ForwardedRef<HTMLDivElement>
): JSX.Element {
  return (
    <Container
      size={size}
      data-testid={dataTestId}
      aria-label={ariaLabel}
      {...props}
      ref={forwardedRef}
    >
      <Dot color={color} size={size} />
      <Dot color={color} size={size} />
      <Dot color={color} size={size} />
    </Container>
  );
}

export const LoadingDots = React.forwardRef(LoadingDotsComponent);
export default LoadingDots;
